async transitionTo(stateId, payload = {}) {
  if (this.isLocked()) return false;

  const targetState = this.states.get(stateId);
  if (!targetState) throw new Error(`Unknown state: ${stateId}`);

  const transitionContext = {
    from: this.currentState?.id || null,
    to: stateId,
    payload,
    timestamp: Date.now(),
  };

  if (!this.#runTransitionGuards(transitionContext)) return false;

  const previousState = this.currentState;
  await this.exitCurrentState();

  // Re-validate — state may have changed during exit
  const validatedTarget = this.states.get(stateId);
  if (!validatedTarget) throw new Error(`State disappeared: ${stateId}`);

  // Call onEnter BEFORE setting currentState
  if (typeof validatedTarget.onEnter === "function") {
    await validatedTarget.onEnter(payload);
  }

  // NOW safe to set current state
  this.currentState = validatedTarget;
  this.stateStack.push(validatedTarget.id);
  this.transitionHistory.push(transitionContext);

  this.invalidateRender();
  eventBus.emit(INTERNAL_EVENTS.STATE_CHANGED, transitionContext);

  return true;
}

