async exitCurrentState() {
  if (!this.currentState) return;

  const state = this.currentState;

  try {
    if (typeof state.onExit === "function") {
      await state.onExit();
    }
  } finally {
    // Always clear currentState, even if onExit throws
    this.currentState = null;
    this.invalidateRender();
  }
}

