lock(lockId, owner = "unknown") {
  if (!lockId) return;

  this.locks.set(lockId, {
    id: lockId,
    owner,
    timestamp: Date.now()
  });

  // Timeout de segurança: 10 segundos
  setTimeout(() => {
    if (this.locks.has(lockId)) {
      console.error(`[StateManager] Lock timeout: ${lockId} owned by ${owner}`);
      this.unlock(lockId);
    }
  }, 10000);

  eventBus.emit(INTERNAL_EVENTS.STATE_LOCKED, { lockId, owner });
}

getLocks() {
  return Array.from(this.locks.entries()).map(([id, data]) => ({
    id,
    owner: data.owner,
    age: Date.now() - data.timestamp
  }));
}

unregisterState(stateId) {
  if (!this.states.has(stateId)) return;

  if (this.stateStack.includes(stateId)) {
    console.error(`Cannot unregister state in stack: ${stateId}`);
    return;
  }

  if (this.currentState?.id === stateId) {
    await this.exitCurrentState();
  }

  this.states.delete(stateId);
}

addOverlay(overlayId, data = {}) {
  if (this.overlays.has(overlayId)) return;

  if (this.overlays.size >= 2) {
    console.warn(`Max overlays reached (2), rejecting: ${overlayId}`);
    return;
  }

  const overlayPriority = { PAUSE: 90, DIALOGUE: 65, INVENTORY: 55, SETTINGS: 75 };
  const newPriority = overlayPriority[overlayId] || 0;

  for (const [existingId, existing] of this.overlays) {
    const existingPriority = overlayPriority[existingId] || 0;
    if (newPriority > existingPriority) {
      this.removeOverlay(existingId);
    } else if (existingPriority > newPriority) {
      return;
    }
  }

  this.overlays.set(overlayId, { id: overlayId, data, createdAt: Date.now() });
  this.invalidateRender();
  eventBus.emit(INTERNAL_EVENTS.OVERLAY_ADDED, { overlayId, data });
}

invalidateRender() {
  const payload = {
    currentState: this.currentState?.id || null,
    overlays: this.getOverlays(),
    timestamp: Date.now(),
    sequence: ++this._renderSequence
  };

  eventBus.emit(INTERNAL_EVENTS.RENDER_INVALIDATED, payload);

  if (this.debug && !this._hasRenderListener) {
    console.warn('[StateManager] No render listener detected.');
  }
}

