const _chainRegistry = new Map();

function emitirCadeia(nomeOrigem, nomeDestino, payload = {}, modulo) {
  const correlationId = `${nomeOrigem}_${Date.now()}_${Math.random()}`;

  const currentDepth = _chainRegistry.get(nomeOrigem)?.depth || 0;
  if (currentDepth + 1 > MAX_CHAIN_DEPTH) {
    console.error(`[RUBRO] Async chain depth exceeded: ${nomeOrigem} → ${nomeDestino}`);
  }

  _chainRegistry.set(correlationId, { origin: nomeOrigem, depth: currentDepth + 1, timestamp: Date.now() });
  setTimeout(() => _chainRegistry.delete(correlationId), 5000);

  return emitir(nomeDestino, payload, modulo);
}

addTransitionGuard(guard, priority = 0, name = "anonymous") {
  this.transitionGuards.push({ fn: guard, priority, name });
  this.transitionGuards.sort((a, b) => b.priority - a.priority);
}

#runTransitionGuards(context) {
  const failedGuards = [];

  for (const guard of this.transitionGuards) {
    try {
      const result = guard.fn(context);
      if (result === false) failedGuards.push(guard.name);
    } catch (error) {
      failedGuards.push(`${guard.name}(error: ${error.message})`);
    }
  }

  if (failedGuards.length > 0) {
    this.#log(`Transition denied by guards: ${failedGuards.join(', ')}`);
    return false;
  }

  return true;
}

async persistState(stateId) {
  const hook = this.persistenceHooks.get(stateId);
  if (!hook) return { success: false, reason: 'no_hook', data: null };

  try {
    const data = await hook();
    return { success: true, data, error: null };
  } catch (error) {
    console.error(`Persistence failed for ${stateId}`, error);
    return { success: false, reason: 'error', error: error.message, data: null };
  }
}

