async cleanup() {
  await this.exitCurrentState();

  this.stateStack = [];
  this.overlays.clear();
  this.transitionHistory = [];
  this.transitionGuards = [];
  this.locks.clear();
  this.persistenceHooks.clear();

  // Clear all registered states to allow fresh registration
  this.states.clear();

  // Reset to BOOT-compatible state
  this.currentState = null;

  this.invalidateRender();
  this.#log("StateManager cleanup completed.");
}
